    "k004": "<span class=\"nav__dd-kicker\">Ce qu'est Enki</span> <a href=\"manifesto.html\"><b>Manifeste</b><span>La lettre — 86 références</span></a> <a href=\"standard.html\"><b>Normes</b><span>Les quatre clauses que nous réclamons</span></a> <a href=\"manifesto.html#enki\"><b>Pourquoi Enki</b><span>Le nom &amp; l'argument</span></a>",
