    "k453": "<input type=\"checkbox\" name=\"j-contrib\" value=\"Capital / donations\" /> Capital / dons",
    "k454": "Détaillez — comment pouvez-vous aider concrètement ?",
    "k455": "Étape 4 / 4 · Confirmer &amp; envoyer",
    "k456": "Où traînez-vous en ligne ? <span class=\"hint\">optionnel · cochez au choix</span>",
    "k457": "<input type=\"checkbox\" name=\"j-channel\" value=\"Discord\" /> Discord",
