    "r90.a77f2d2326e3": "<span class=\"abadge\">{{svg1}}Aucune cotisation, jamais</span><span class=\"abadge\">{{svg2}}L’un des 300 sièges</span><span class=\"abadge\">Examen humain prévu</span>",
